return [
  { json: { name: 'Nusantara Post', url: 'https://www.nusantarapost.news', redisKey: 'uptime:nusantarapost' } },
  { json: { name: 'Klik Wartaku', url: 'https://klikwartaku.com', redisKey: 'uptime:klikwartaku' } }
];

const src = $('Site List').item.json;
const statusCode = $json.statusCode ?? 0;
const statusMessage = $json.statusMessage || '';
const up = statusCode >= 200 && statusCode < 300;

// Server merespons dengan HTTP valid = situs hidup. 401/403/429 artinya
// WAF/Cloudflare/rate-limit memblokir kita, bukan situs mati.
const BLOCKED_CODES = [401, 403, 429];
const blocked = !up && BLOCKED_CODES.indexOf(statusCode) !== -1;

const HTTP_HINT = {
  401: 'butuh autentikasi (proteksi CDN/admin area)',
  403: 'DITOLAK WAF/Cloudflare atau IP monitor diblokir',
  404: 'halaman tidak ada, path salah atau situs belum ter-deploy',
  405: 'method tidak diizinkan di path ini',
  429: 'rate limited, terlalu banyak request',
  500: 'error internal aplikasi di origin',
  502: 'bad gateway, origin di belakang proxy/CDN tidak merespons',
  503: 'situs maintenance atau origin overload',
  504: 'gateway timeout, origin lambat melebihi batas proxy',
  520: 'error Cloudflare, origin menolak koneksi',
  521: 'origin menolak koneksi, web server mati',
  522: 'koneksi ke origin timeout (Cloudflare)',
  523: 'origin tidak bisa dijangkau (Cloudflare)',
  524: 'origin tidak merespons sampai Cloudflare timeout',
};

let reason = '';
if (!up) {
  reason = 'HTTP ' + statusCode + (statusMessage ? ' ' + statusMessage : '');
  if (HTTP_HINT[statusCode]) reason += ' - ' + HTTP_HINT[statusCode];
}

return { json: {
  name: src.name,
  url: src.url,
  redisKey: src.redisKey,
  status: up ? 'up' : blocked ? 'blocked' : 'down',
  statusCode,
  reason,
  netError: false,
} };

const src = $json.name ? $json : $('Site List').item.json;
const err = $json.error || {};
const det = $json.details || {};
const code = String(err.code || det.httpCode || '').trim();
const rawMsg = String(err.message || det.message || '').trim();

const EXPLAIN = {
  EAI_AGAIN: 'DNS lookup gagal sementara, resolver DNS tidak merespons atau kena rate-limit',
  ENOTFOUND: 'domain tidak ditemukan di DNS, tidak ada record A/AAAA',
  ECONNREFUSED: 'koneksi ditolak server, port tertutup atau service di origin mati',
  ECONNRESET: 'koneksi diputus di tengah request oleh server',
  ECONNABORTED: 'timeout, server tidak mengirim response header dalam batas waktu',
  ETIMEDOUT: 'timeout, server tidak merespons dalam batas waktu',
  ESOCKETTIMEDOUT: 'timeout, koneksi socket tidak merespons',
  EHOSTUNREACH: 'host tidak bisa dijangkau, masalah routing atau firewall',
  ENETUNREACH: 'jaringan tidak bisa dijangkau, koneksi internet host n8n bermasalah',
  EPROTO: 'TLS handshake gagal, versi TLS tidak cocok',
  DEPTH_ZERO_SELF_SIGNED_CERT: 'sertifikat TLS self-signed, tidak trusted',
  UNABLE_TO_VERIFY_LEAF_SIGNATURE: 'sertifikat TLS tidak bisa diverifikasi, CA tidak dikenal',
  SELF_SIGNED_CERT_IN_CHAIN: 'sertifikat TLS self-signed ada di dalam chain',
  CERT_HAS_EXPIRED: 'sertifikat TLS sudah kedaluwarsa',
  ERR_TLS_CERT_ALTNAME_INVALID: 'sertifikat TLS tidak cocok dengan hostname situs',
  ERR_FR_TOO_MANY_REDIRECTS: 'redirect loop, terlalu banyak hop redirect',
  ERR_FR_CONNECTION_RESET: 'koneksi di-reset saat mengikuti redirect',
  ERR_INVALID_URL: 'URL tidak valid',
  ERR_BAD_RESPONSE: 'respons server tidak valid atau terpotus di tengah jalan',
  ERR_BAD_REQUEST: 'respons server tidak valid atau terpotus di tengah jalan',
  PROTOCOL_ERROR: 'protokol error, server memutus koneksi HTTP',
};

let reason;
if (EXPLAIN[code]) {
  reason = EXPLAIN[code] + ' [' + code + ']';
} else {
  const t = rawMsg.match(/timeout of (\d+)ms/i);
  if (t) {
    reason = 'timeout ' + Math.round(Number(t[1]) / 1000) + ' detik, server tidak merespons';
  } else if (rawMsg) {
    reason = (code ? code + ': ' : '') + rawMsg;
  } else {
    reason = 'koneksi gagal tanpa detail error';
  }
}

return { json: {
  name: src.name,
  url: src.url,
  redisKey: src.redisKey,
  status: 'down',
  statusCode: 0,
  reason,
  netError: true,
} };

const NEED_FAIL = 2;
const NEED_OK = 2;
const REPEAT_MS = 6 * 3600 * 1000;

// Redis "get" REPLACES item json, so site fields must come from Combine Results via pairedItem.
const srcAll = $('Combine Results').all();
const items = $input.all();

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stamp = () => $now.setZone('Asia/Jakarta').toFormat('dd LLL yyyy HH:mm') + ' WIB';
const dur = (ms) => {
  const s = Math.round(ms / 1000);
  if (s < 60) return s + 's';
  const m = Math.floor(s / 60);
  if (m < 60) return m + 'm ' + (s % 60) + 's';
  const h = Math.floor(m / 60);
  if (h < 24) return h + 'h ' + (m % 60) + 'm';
  return Math.floor(h / 24) + 'd ' + (h % 24) + 'h';
};

const probes = items.map((it, i) => {
  const raw = srcAll[it.pairedItem && it.pairedItem.item !== undefined ? it.pairedItem.item : i] || {};
  return { src: raw.json || {}, lastRaw: it.json.lastRaw };
});

const netFails = probes.filter((p) => p.src.netError).length;
const allNetDown = probes.length > 1 && netFails === probes.length;

const suspect = allNetDown
  ? '<b>MONITOR SUSPECT</b>\nSemua ' + probes.length
    + ' site gagal karena error jaringan di host n8n (bukan situs mati).\n'
    + probes.map((p) => ' - ' + esc(p.src.name) + ': ' + esc(p.src.reason)).join('\n')
    + '\n\nCek DNS/resolver host n8n dulu sebelum menganggap situs down.'
  : '';

const now = Date.now();
const out = [];

probes.forEach((p, idx) => {
  const j = p.src;

  let st = null;
  if (typeof p.lastRaw === 'string' && p.lastRaw) {
    try { const parsed = JSON.parse(p.lastRaw); if (parsed && typeof parsed === 'object') st = parsed; } catch (e) { st = null; }
  }
  if (!st) {
    const legacy = p.lastRaw === 'up' || p.lastRaw === 'down' ? p.lastRaw : null;
    st = { status: legacy, checks: 0, upChecks: 0, downChecks: 0, downMs: 0, observedMs: 0,
           lastCheckAt: null, downSince: null, lastReason: '', pending: null, alerts: {} };
  }

  const prev = st.status || null;
  const cur = j.status;
  let message = '';
  let retryOf = null;

  if (allNetDown) {
    st.skipped = (st.skipped || 0) + 1;
    if (idx === 0 && suspect) message = suspect;
  } else {
    st.skipped = 0;
    const dt = st.lastCheckAt ? Math.max(0, now - st.lastCheckAt) : 0;
    st.checks = (st.checks || 0) + 1;
    st.lastCheckAt = now;
    st.observedMs = (st.observedMs || 0) + dt;

    const reachable = cur === 'up' || cur === 'blocked';
    if (reachable) {
      st.upChecks = (st.upChecks || 0) + 1;
      st.failStreak = 0;
      st.okStreak = (st.okStreak || 0) + 1;
      if (cur === 'blocked') st.blockedChecks = (st.blockedChecks || 0) + 1;
    } else {
      st.downChecks = (st.downChecks || 0) + 1;
      st.failStreak = (st.failStreak || 0) + 1;
      st.okStreak = 0;
      if (prev !== 'down') st.downSince = now;
    }

    let recoveredMs = null;
    if (reachable && st.downSince && st.okStreak >= NEED_OK) {
      recoveredMs = Math.max(0, now - st.downSince);
      st.downMs = (st.downMs || 0) + recoveredMs;
      st.downSince = null;
    }

    st.lastReason = j.reason || '';
    st.status = cur;

    const pct = st.observedMs > 0
      ? Math.max(0, Math.min(100, (1 - st.downMs / st.observedMs) * 100)).toFixed(2)
      : null;
    const uptimeLine = st.checks + ' cek, uptime ' + (pct === null ? 'n/a' : pct + '%');

    const alerts = st.alerts && typeof st.alerts === 'object' ? st.alerts : {};
    const due = (kind) => !alerts[kind] || now - alerts[kind] >= REPEAT_MS;

    retryOf = st.pending;
    if (retryOf) {
      message = retryOf + '\n\n(terlambat: alert sebelumnya gagal terkirim)';
    } else if (cur === 'down') {
      if (prev !== 'down') st.downAlerted = false;
      const confirmed = st.failStreak >= NEED_FAIL || prev === null;
      if (confirmed && (!st.downAlerted || due('down'))) {
        st.downAlerted = true;
        alerts.down = now;
        message = '<b>DOWN ' + esc(j.name) + '</b>\n' + esc(j.url) + '\n'
          + 'Reason: ' + esc(j.reason || 'unknown') + '\n'
          + 'Streak: ' + st.failStreak + ' gagal berturut-turut\n'
          + uptimeLine + '\n'
          + 'Time: ' + stamp();
      }
    } else if (recoveredMs !== null) {
      alerts.recovered = now;
      message = '<b>RECOVERED ' + esc(j.name) + '</b>\n' + esc(j.url) + '\n'
        + 'Downtime: ' + dur(recoveredMs) + '\n'
        + uptimeLine + '\n'
        + 'Time: ' + stamp();
    } else if (cur === 'blocked') {
      // stay quiet while an outage is still waiting for confirmed recovery
      if (!st.downSince && (prev !== 'blocked' || due('blocked'))) {
        alerts.blocked = now;
        message = '<b>BLOCKED ' + esc(j.name) + '</b>\n' + esc(j.url) + '\n'
          + 'Reason: ' + esc(j.reason || 'unknown') + '\n'
          + 'Server merespon tapi memblokir request monitor (WAF/Cloudflare/rate limit).\n'
          + 'Tidak dihitung downtime, user nyata mungkin tidak terpengaruh.\n'
          + uptimeLine + '\n'
          + 'Time: ' + stamp();
      }
    }
    st.alerts = alerts;
  }

  // Persist the alert intent BEFORE sending. Cleared by Save Alert Sent only after Telegram
  // actually accepted the message, so a failed send is retried on the next run.
  // retryOf is kept verbatim so the retry text never grows.
  st.pending = retryOf || message || null;

  out.push({ json: Object.assign({}, j, {
    lastRaw: p.lastRaw,
    shouldAlert: !!message,
    message,
    state: JSON.stringify(st),
  }) });
});
return out;

const src = $('Save Current Status').item.json;
let st = {};
try { st = JSON.parse(src.state) || {}; } catch (e) { st = {}; }
st.pending = null;
return { json: Object.assign({}, src, { state: JSON.stringify(st) }) };
